mapper.select:
SELECT id, workspace_id, name, color FROM tag
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT EXISTS(
  SELECT 1 FROM tag WHERE workspace_id = #{workspaceId} AND id = #{id}
)

choose.when:
SELECT pt.person_id AS record_id, t.id AS tag_id, t.name
FROM person_tag pt
JOIN person r ON r.id = pt.person_id AND r.workspace_id = #{workspaceId}
JOIN tag t ON t.id = pt.tag_id AND t.workspace_id = #{workspaceId}
WHERE pt.person_id IN
  #{id}
ORDER BY pt.person_id, t.name

SELECT ct.company_id AS record_id, t.id AS tag_id, t.name
FROM company_tag ct
JOIN company r ON r.id = ct.company_id AND r.workspace_id = #{workspaceId}
JOIN tag t ON t.id = ct.tag_id AND t.workspace_id = #{workspaceId}
WHERE ct.company_id IN
  #{id}
ORDER BY ct.company_id, t.name

SELECT dt.deal_id AS record_id, t.id AS tag_id, t.name
FROM deal_tag dt
JOIN deal r ON r.id = dt.deal_id AND r.workspace_id = #{workspaceId}
JOIN tag t ON t.id = dt.tag_id AND t.workspace_id = #{workspaceId}
WHERE dt.deal_id IN
  #{id}
ORDER BY dt.deal_id, t.name
